INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(30369, 'koKR', 'Ssssłudzy łussski, usssłyszcie mój zew!', '', 0),
(30370, 'koKR', 'Tysssiąc kłów rozszarpie wasze ciała!', '', 0),
(30385, 'koKR', '%s zaczyna się przemieniać!', '', 0),
(30388, 'koKR', '%s przemienia się w mamuta!', '', 0),
(30740, 'koKR', 'Coś się porusza w sadzawce mojo...', '', 0),
(30757, 'koKR', '%s zaczyna rzucać Rozbłysk trucizny!', '', 0),
(31199, 'koKR', 'Gdy %s pada, ołtarz wpuszczony w posadzkę jego balkonu zaczyna słabo jaśnieć.', '', 0),
(31427, 'koKR', 'My odeprzeć Plagę. Jaką szansę ty myśleć, że TY mieć?', '', 0),
(31428, 'koKR', 'Szykujcie się na coś... dużo... WIĘKSZEGO!', '', 0),
(31429, 'koKR', 'Ziemia was pochłonąć!', '', 0),
(31430, 'koKR', 'Ja was zgnieść, karaluchy!', '', 0),
(31431, 'koKR', 'Kto mnie powstrzymać? Ty?', '', 0),
(31432, 'koKR', 'Już nie być tacy twardzi!!', '', 0),
(31433, 'koKR', 'Jeśli nasi bogowie mogą umrzeć... to my też...', '', 0),
(31711, 'koKR', 'Drakkari zabiją każdego, kto ośmieli sssię wtargnąć na te ziemie!', '', 0),
(31712, 'koKR', 'Nie oddychasssz? Dobrze.', '', 0),
(31713, 'koKR', 'Ssstrach cię oblatuje?', '', 0),
(31714, 'koKR', 'Teraz zjem ciebie, mon.', '', 0),
(31715, 'koKR', 'Teraz rozumiem... to nie Plaga była... naszym najwięksssym wrogiem...', '', 0);
